cat << 'EOF' > src/orchestration/tools/registry.test.ts
import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  describe('execute', () => {
    it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
      const registry = new ToolRegistry();
      let executorCalls = 0;
      const definition: ToolDefinition = {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      };
      registry.register(definition, async () => {
        executorCalls += 1;
        return 'sunny';
      });

      const response = await registry.execute('get_weather', {});

      expect(executorCalls).toBe(0);
      expect(response.result).toContain('location');
      expect(response.result).toMatch(/required/i);
    });
  });
});
EOF
